package com.dropai.generator;
import com.dropai.generator.blueprint.*;import com.dropai.generator.engine.*;import org.junit.jupiter.api.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class OneToManyVerticalSliceTest{@Test void expandsLaboratoryDeviceRelation()throws Exception{Path fixture=Path.of("..","docs","blueprints","laboratory-device-one-to-many.blueprint.json");BlueprintPipeline p=new BlueprintPipeline();var model=p.normalize(p.parse(Files.readAllBytes(fixture)));assertEquals(2,model.entities().size());assertEquals("laboratoryId",model.relations().get(0).foreignKeyName());var device=model.entities().stream().filter(e->e.className().equals("Device")).findFirst().orElseThrow();assertTrue(device.fields().stream().anyMatch(f->f.name().equals("laboratoryId")&&f.relationField()));Path out=Files.createTempDirectory("dokiai-one-many-");try(TemplateEngine engine=new TemplateEngine()){Path root=engine.generate(model,out);String sql=Files.readString(root.resolve("sql/database.sql"));assertTrue(sql.contains("FOREIGN KEY (`laboratory_id`)"));assertTrue(sql.contains("ON DELETE RESTRICT"));String vo=Files.readString(root.resolve("backend/src/main/java/com/dokiai/laboratory/vo/DeviceVO.java"));assertTrue(vo.contains("laboratoryName"));String vue=Files.readString(root.resolve("frontend/src/views/device/index.vue"));assertTrue(vue.contains("el-select"));assertTrue(vue.contains("relationOptions"));}finally{try(var paths=Files.walk(out)){for(Path x:paths.sorted(java.util.Comparator.reverseOrder()).toList())Files.deleteIfExists(x);}}}}
